<?php

declare(strict_types=1);

namespace SugarCraft\Code\Workflows;

/**
 * One-line glosses for every word of the YAML workflow grammar, and the
 * compact grammar paragraph the model-facing `Workflow` tool builds from them
 * (wf-impl P0-1).
 *
 * WHY A SEPARATE ROSTER: the tool's description used to be hand-written prose
 * that named a fifth of the grammar, so every feature landed after it was
 * invisible to the model. The paragraph is now generated by walking the
 * loader's own rosters ({@see Workflow::STAGE_TYPES},
 * {@see WorkflowRegistry::YAML_TASK_KEYS} and the registry's stage-key list),
 * and {@see \SugarCraft\Code\Tests\Tools\WorkflowToolDescriptionDriftTest}
 * holds this file set-equal to them: a key the loader learns without a gloss
 * here — or a gloss for a key the loader refuses — goes red.
 *
 * The registry's stage-key roster is private, so {@see self::STAGE_KEYS} is
 * the order the paragraph prints and the drift test compares it to the
 * registry's constant by reflection rather than widening the registry's
 * surface for a doc concern.
 *
 * Glosses describe what the loader and engine do TODAY, in literal English;
 * patterns and worked examples belong to the `workflow-authoring` skill.
 */
final class WorkflowGrammarGlossary
{
    /** Top-level document keys (no loader roster exists for these; not drift-pinned). */
    public const WORKFLOW_KEYS = [
        'name' => 'the plan\'s name (defaults to "plan" in the tool)',
        'description' => 'one line of intent',
        'stages' => 'the ordered stage list (required)',
        'config' => '`{timeout: seconds per stage (default 3600), maxConcurrent: in-flight agent width (unset = min(16, CPUs-2), 0 = no cap), maxAgents: run-wide dispatch ceiling counting retries and loop rounds (default ' . Workflow::DEFAULT_MAX_AGENTS . ')}`',
        'schemas' => 'a map of name => object-rooted JSON Schema; any task\'s `outputSchema: {$ref: name}` resolves to it at load',
    ];

    /** @var array<string, string> keyed by every {@see Workflow::STAGE_TYPES} entry */
    public const STAGE_TYPES = [
        'stage' => 'the default: one task (task keys on the stage itself) or a `tasks:` list run in order, each later task seeing `{{prevResult}}`',
        'parallel' => '`parallel: true` (or `type: parallel`) with an `agents:` list, or `from:` plus a template `prompt`; every agent runs, then the stage settles',
        'pipeline' => '`type: pipeline` with a nested `stages:` list of steps run in order for one item, each step seeing `{{prevResult}}`',
        'verification' => '`type: verification` with a `task:` map and a `verifier:` map that judges the task\'s output (`{{prevResult}}`); `reject` on the verifier fails the stage, `votes`/`lenses`/`quorum` turn the verifier into a panel judged by quorum, and a line starting `ESCALATE:` stops the run for a human',
    ];

    /** @var array<string, string> keyed by every registry stage key, in print order */
    public const STAGE_KEYS = [
        'name' => 'unique stage name; later prompts read `{{name.output}}`',
        'type' => 'stage shape: `stage` (default), `parallel`, `pipeline` or `verification`',
        'parallel' => '`true` is the flag spelling of `type: parallel`; never spell both',
        'agents' => 'parallel only: the list of task maps (the label is spelled `type:` here, not `agent:`)',
        'tasks' => 'a list of task maps run in order inside one stage; the first failure stops the stage',
        'task' => 'verification only: the task map that does the work',
        'verifier' => 'verification only: the task map that judges it',
        'stages' => 'pipeline only: the nested list of step maps',
        'from' => 'parallel fan-out over exactly one source, one task per item from a template `prompt`: `{glob: "src/**/*.php"}` (files, `{{path}}`), `{stage: find, pointer: /findings, key: /id}` (an array in a prior stage\'s typed row; `key` dedups and names items) or `{context: files}` (a run-context list); `{{item}}`, `{{item.<pointer>}}`, `{{index}}` read the item, `chunk: N` caps in-flight width, `max: N` keeps the first N and lists the dropped rest (ceiling ' . Workflow::FAN_OUT_CEILING . ' items); an empty data list completes with no agents',
        'when' => 'skip the stage unless a clause over an earlier stage\'s output holds: `{stage: s, equals|contains|matches: v}` or `{stage: s, empty: true|false}`, optionally `pointer: /leaf` to judge a schema\'d stage\'s JSON instead of its text, or `{all|any: [leaves]}` (one nesting level); a stage that never ran or a pointer that misses is unsatisfied, and a skip is not a failure',
        'loop' => 'stage, parallel and verification stages: `{max: N, until: <when-clause>}` re-runs the stage (seeing `{{round}}` and, from round 2, `{{previous}}`) until the clause holds; hitting `max` completes with the last round. `accumulate: {pointer: /findings, key: /id}` keeps a deduped item set across rounds (`{{seen}}` keys, `{{fresh}}` last round\'s new items) and makes the stage\'s result `{"items":[…],"keys":[…],"rounds":n}`; `until: {dry: N}` stops after N rounds that added nothing new',
        'capture' => '`true` writes the full output to a file; later prompts get the path plus a 2 KiB preview',
        'cache' => '`true` lets a resumed run carry this stage\'s recorded successful result when its declaration is unchanged',
        'uses' => 'run another saved workflow (by name) as this stage\'s body; depth at most ' . WorkflowEngine::MAX_USES_DEPTH . ', no cycles',
        'minSuccess' => 'parallel only: `N` agents or `"NN%"` must succeed (default all); when met the stage completes, lists its casualties and exposes them as `{{stage.failed}}`',
        'with' => 'with `uses:` only: context values handed to the included workflow (may interpolate, e.g. `"{{research.output}}"`)',
    ];

    /** @var array<string, string> keyed by every {@see WorkflowRegistry::YAML_TASK_KEYS} entry */
    public const TASK_KEYS = [
        'agent' => 'display label only (spelled `type:` inside `agents:`; default `coder`)',
        'name' => 'result name, read as `{{name.results}}`; use underscores, a hyphenated name cannot be referenced',
        'prompt' => 'the entire instruction; stage agents do not see this conversation, so make it self-contained',
        'tools' => 'allowed tools, argument-scoped entries allowed (`Bash(git *)`); omitted = this session\'s tools, `[]` = none',
        'retries' => 're-run after a failure or timeout; only on agents that are safe to run twice',
        'outputSchema' => 'a JSON Schema (map, inline JSON string or file path) for a structured answer, read later with `{{stage.<pointer>}}`',
        'isolation' => '`worktree` runs the agent in its own git worktree, never auto-merged',
        'model' => 'run this task on a named model instead of the session\'s',
        'resource' => 'an exclusive host lock name held for the whole stage (one GPU, one display)',
        'lockWaitSeconds' => 'seconds to wait for that `resource` lock before the stage fails (default 60)',
        'timeout' => 'this task\'s own seconds; the smaller of it and the stage budget wins',
        'reject' => 'verifier only: a PCRE whose match in the verdict fails the stage',
        'rejectMinOccurrences' => 'verifier only: how many `reject` matches make a rejection (default 1)',
        'stallTimeout' => 'expire a worker that publishes no progress for N seconds',
        'restarts' => 're-dispatch budget for stalled workers, separate from `retries`',
        'input' => '`{from: [stageA, stageB], as: file-list|first|all|results}` joins prior stages into `{{input}}`',
        'votes' => 'verifier only: N independent verifier dispatches run concurrently on the stage budget (default 1); a vote rejects when its output matches `reject` or it fails/times out, an `ESCALATE:` line in any vote stops the run, and `retries` re-runs the whole panel',
        'lenses' => 'verifier only: one lens name per vote (length must equal `votes`), interpolated as `{{lens}}` into that vote\'s prompt',
        'quorum' => 'verifier only: how many votes must NOT reject for the verdict to pass, 1..votes (default the majority, floor(votes/2)+1)',
    ];

    /** @var array<string, string> interpolation form => what it resolves to */
    public const INTERPOLATION = [
        '{{key}}' => 'a `context` value (arrays and objects render as compact JSON)',
        '{{stage.output}}' => 'a prior stage\'s output (parallel: agent outputs joined by newlines)',
        '{{name.results}}' => 'one agent\'s output by result name (unnamed: `<stage>`, `<stage>_<n>` in parallel, `<stage>_verifier`)',
        '{{stage.<pointer>}}' => 'an RFC 6901 leaf of a schema\'d stage\'s JSON (`{{find.items/0/id}}`; dots do not nest)',
        '{{prevResult}}' => 'the previous task/step output in a `tasks:` list or pipeline, or the task\'s output inside a verifier',
        '{{input}}' => 'the `input:` join',
        '{{path}}' => 'the current file in a `from: {glob}` fan-out',
        '{{item}}' => 'the current `from:` fan-out item (a string verbatim, anything else as JSON); `{{item.<pointer>}}` reads a leaf of it',
        '{{index}}' => 'the 0-based position of the current `from:` fan-out item',
        '{{round}}' => 'the 1-based round inside a `loop:`',
        '{{previous}}' => 'the prior round\'s stage output inside a `loop:` (left verbatim in round 1)',
        '{{seen}}' => 'inside a `loop:` with `accumulate`: the JSON list of every dedup key collected so far',
        '{{fresh}}' => 'inside a `loop:` with `accumulate`: the JSON list of the items the previous round added',
        '{{stage.failed}}' => 'the JSON list of a `minSuccess` stage\'s failed agent names',
        '{{lens}}' => 'inside a verifier vote: that vote\'s entry of `lenses` (verbatim when the verifier declares no lenses)',
        '{{stage.votes}}' => 'a verifier panel\'s votes as JSON, `[{lens, rejected, output|data}]` (`data` when the verifier has an outputSchema)',
    ];

    /**
     * The grammar paragraph: shapes first, then one line per key, walked in
     * the LOADER'S roster order for types and task keys so a key the loader
     * learns appears here even before it has a gloss (printed bare — the
     * drift test is what reddens on the missing gloss, not the model).
     *
     * @param list<string> $stageKeys the registry's stage-key roster, print order
     */
    public static function grammar(?array $stageKeys = null): string
    {
        $stageKeys ??= array_keys(self::STAGE_KEYS);

        $lines = ['Plan (YAML) top level: ' . self::inline(self::WORKFLOW_KEYS, array_keys(self::WORKFLOW_KEYS)) . '.'];

        $lines[] = 'Stage shapes:';
        foreach (Workflow::STAGE_TYPES as $type) {
            $lines[] = self::line($type, self::STAGE_TYPES[$type] ?? null);
        }

        $lines[] = 'Stage keys:';
        foreach ($stageKeys as $key) {
            $lines[] = self::line($key, self::STAGE_KEYS[$key] ?? null);
        }

        $lines[] = 'Task keys (on a plain stage, a `tasks:` or `agents:` entry, a pipeline step, a verification `task:`/`verifier:`):';
        foreach (WorkflowRegistry::YAML_TASK_KEYS as $key) {
            $lines[] = self::line($key, self::TASK_KEYS[$key] ?? null);
        }

        $lines[] = 'Interpolation (an unresolved token stays verbatim in the prompt):';
        foreach (self::INTERPOLATION as $form => $gloss) {
            $lines[] = "- `{$form}`: {$gloss}";
        }

        return implode("\n", $lines);
    }

    private static function line(string $key, ?string $gloss): string
    {
        return $gloss === null ? "- `{$key}`" : "- `{$key}`: {$gloss}";
    }

    /**
     * @param array<string, string> $glosses
     * @param list<string>          $keys
     */
    private static function inline(array $glosses, array $keys): string
    {
        return implode('; ', array_map(static fn (string $k): string => "`{$k}` = {$glosses[$k]}", $keys));
    }
}
